import numpy as np
from scipy.optimize import linprog

R_MIN = 1e-8

def solve_exact_radii_lp(centers):
    n = 32; c = -np.ones(n); A_ub, b_ub = [], []
    for i in range(n):
        x_i, y_i = centers[i]; r1=np.zeros(n); r1[i]=1; A_ub.append(r1); b_ub.append(x_i); r2=np.zeros(n); r2[i]=1; A_ub.append(r2); b_ub.append(1-x_i); r3=np.zeros(n); r3[i]=1; A_ub.append(r3); b_ub.append(y_i); r4=np.zeros(n); r4[i]=1; A_ub.append(r4); b_ub.append(1-y_i)
    for i in range(n):
        for j in range(i + 1, n):
            dist = np.linalg.norm(centers[i] - centers[j]); row = np.zeros(n); row[i]=1; row[j]=1; A_ub.append(row); b_ub.append(dist)
    bounds = [(R_MIN, 0.5)] * n
    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub), bounds=bounds, method='highs')
    return res.x, -res.fun if res.success else (np.full(n, R_MIN), n*R_MIN)

def solve_center_update_lp(centers_0, delta):
    n = 32; c = np.concatenate([np.zeros(2*n), -np.ones(n)]); A_ub, b_ub = [], []
    for i in range(n):
        row=np.zeros(3*n); row[i]=-1; row[2*n+i]=1; A_ub.append(row); b_ub.append(0); row=np.zeros(3*n); row[i]=1; row[2*n+i]=1; A_ub.append(row); b_ub.append(1); row=np.zeros(3*n); row[n+i]=-1; row[2*n+i]=1; A_ub.append(row); b_ub.append(0); row=np.zeros(3*n); row[n+i]=1; row[2*n+i]=1; A_ub.append(row); b_ub.append(1)
    for i in range(n):
        for j in range(i+1, n):
            c_i, c_j = centers_0[i], centers_0[j]; d_ij = np.linalg.norm(c_i - c_j)
            if d_ij < 1e-9: continue
            u_ij = (c_i - c_j) / d_ij; row = np.zeros(3*n)
            row[i]=-u_ij[0]; row[j]=u_ij[0]; row[n+i]=-u_ij[1]; row[n+j]=u_ij[1]; row[2*n+i]=1; row[2*n+j]=1; A_ub.append(row)
            # --- FINAL BUG FIX --- The RHS of the constraint is d_ij, not 0.
            b_ub.append(d_ij)
    bounds = []
    for i in range(n): bounds.append((centers_0[i,0]-delta, centers_0[i,0]+delta));
    for i in range(n): bounds.append((centers_0[i,1]-delta, centers_0[i,1]+delta));
    bounds.extend([(R_MIN, 0.5)]*n)
    res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub), bounds=bounds, method='highs')
    return res.x if res.success else None

def run_mm_lp_loop(centers, num_iterations, delta):
    best_centers = np.copy(centers); _, best_score = solve_exact_radii_lp(centers)
    for _ in range(num_iterations):
        x_new = solve_center_update_lp(centers, delta)
        if x_new is None: break
        centers_new = x_new[:64].reshape((32, 2)); _, score_new = solve_exact_radii_lp(centers_new)
        if score_new > best_score + 1e-9:
            best_score = score_new; best_centers = centers_new; centers = centers_new
        else: break
    return best_centers, best_score

def iterative_finalize(centers, radii):
    n=32; final_radii=np.copy(radii); epsilon=1e-9
    for _ in range(10):
        v=0
        for i in range(n):
            x,y=centers[i]; r=min(final_radii[i],x,1-x,y,1-y)
            if r<final_radii[i]: final_radii[i]=r; v+=1
        for i in range(n):
            for j in range(i+1, n):
                d=np.linalg.norm(centers[i]-centers[j]); s=final_radii[i]+final_radii[j]
                if s>=d-epsilon:
                    o=s-(d-epsilon); red=o/2.0; r_i=max(R_MIN,final_radii[i]-red); r_j=max(R_MIN,final_radii[j]-red)
                    if r_i<final_radii[i] or r_j<final_radii[j]: final_radii[i]=r_i; final_radii[j]=r_j; v+=1
        if v==0: break
    return final_radii

def construct_packing() -> tuple:
    n=32; num_prospects=128; num_elites=16; rng=np.random.default_rng(42)
    prospects=[]
    for i in range(num_prospects):
        p_centers=rng.random((n,2)); ref_centers,score=run_mm_lp_loop(p_centers,10,0.05)
        prospects.append({'centers':ref_centers,'score':score})
    prospects.sort(key=lambda p: p['score'], reverse=True); elites=prospects[:num_elites]
    best_centers=elites[0]['centers']; best_score=elites[0]['score']
    for elite in elites:
        ref_centers,score=run_mm_lp_loop(elite['centers'],30,0.02)
        if score>best_score: best_score=score; best_centers=ref_centers
    lp_radii,_=solve_exact_radii_lp(best_centers)
    final_radii=iterative_finalize(best_centers,lp_radii)
    return best_centers, final_radii
